-- Esquema de referencia generado desde las migraciones de Django (solo para pruebas de la API Flask).
-- Regenerar con: python manage.py migrate en una base vacía y volcar sqlite_master.
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "core_agricultor" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(150) NOT NULL, "telefono" varchar(20) NOT NULL, "comuna" varchar(100) NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "rut" varchar(12) NULL UNIQUE);
CREATE TABLE "core_zona" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL UNIQUE, "descripcion" text NOT NULL, "activo" bool NOT NULL);
CREATE TABLE "core_cultivo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(150) NOT NULL UNIQUE, "descripcion" text NOT NULL, "rendimiento_ton_ha" decimal NULL, "densidad_siembra" decimal NULL, "unidad_siembra" varchar(20) NOT NULL, "activo" bool NOT NULL, "densidad_fuente" varchar(255) NOT NULL, "densidad_url" varchar(200) NOT NULL, "densidad_verificada" date NULL, "rendimiento_fuente" varchar(255) NOT NULL, "rendimiento_url" varchar(200) NOT NULL, "rendimiento_verificado" date NULL);
CREATE TABLE "core_tipoinsumo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL UNIQUE);
CREATE TABLE "core_insumo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(150) NOT NULL, "descripcion" text NOT NULL, "dosis_hectarea" decimal NULL, "unidad_dosis" varchar(50) NOT NULL, "vigente" bool NOT NULL, "cultivo_id" bigint NULL REFERENCES "core_cultivo" ("id") DEFERRABLE INITIALLY DEFERRED, "tipo_id" bigint NOT NULL REFERENCES "core_tipoinsumo" ("id") DEFERRABLE INITIALLY DEFERRED, "zona_id" bigint NULL REFERENCES "core_zona" ("id") DEFERRABLE INITIALLY DEFERRED, "advertencia_polinizadores" text NOT NULL, "composicion_nutricional" varchar(255) NOT NULL, "concentracion" varchar(100) NOT NULL, "cultivos_autorizados" text NOT NULL CHECK ((JSON_VALID("cultivos_autorizados") OR "cultivos_autorizados" IS NULL)), "dosis_fuente" varchar(255) NOT NULL, "dosis_verificada" bool NOT NULL, "estado_verificacion" varchar(12) NOT NULL, "etiqueta_url" varchar(200) NOT NULL, "fabricante" varchar(150) NOT NULL, "fecha_verificacion" date NULL, "formulacion" varchar(100) NOT NULL, "fosforo_p2o5_pct" decimal NULL, "fuente_nombre" varchar(255) NOT NULL, "fuente_url" varchar(200) NOT NULL, "germinacion_pct" decimal NULL, "hoja_seguridad_url" varchar(200) NOT NULL, "ingrediente_activo" varchar(255) NOT NULL, "nitrogeno_pct" decimal NULL, "numero_autorizacion_sag" varchar(100) NOT NULL, "objetivos_control" text NOT NULL CHECK ((JSON_VALID("objetivos_control") OR "objetivos_control" IS NULL)), "periodo_carencia" varchar(100) NOT NULL, "peso_mil_semillas_g" decimal NULL, "plantas_objetivo_m2" decimal NULL, "potasio_k2o_pct" decimal NULL, "precauciones_ambientales" text NOT NULL, "presentacion_cantidad" decimal NULL, "presentacion_unidad" varchar(50) NOT NULL, "pureza_pct" decimal NULL, "restricciones" text NOT NULL, "tiempo_reingreso" varchar(100) NOT NULL, "tipo_semilla" varchar(100) NOT NULL, "variedad_semilla" varchar(150) NOT NULL, "dosis_maxima_hectarea" decimal NULL, "unidad_dosis_maxima" varchar(50) NOT NULL, "vigencia_desde" date NULL, "vigencia_hasta" date NULL, "modo_aplicacion" text NOT NULL);
CREATE INDEX "core_insumo_cultivo_id_14918a05" ON "core_insumo" ("cultivo_id");
CREATE INDEX "core_insumo_tipo_id_7e046211" ON "core_insumo" ("tipo_id");
CREATE INDEX "core_insumo_zona_id_1e0b3323" ON "core_insumo" ("zona_id");
CREATE TABLE "core_predio" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(150) NOT NULL, "ubicacion" varchar(255) NOT NULL, "superficie_ha" decimal NOT NULL, "creado" datetime NOT NULL, "propietario_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "zona_id" bigint NULL REFERENCES "core_zona" ("id") DEFERRABLE INITIALLY DEFERRED, "geojson" text NULL CHECK ((JSON_VALID("geojson") OR "geojson" IS NULL)), "latitud" real NULL, "longitud" real NULL, "actualizado" datetime NOT NULL, "descripcion" text NOT NULL, "observaciones" text NOT NULL, CONSTRAINT "predio_superficie_positiva" CHECK ("superficie_ha" > '0'));
CREATE INDEX "core_predio_propietario_id_8f611072" ON "core_predio" ("propietario_id");
CREATE INDEX "core_predio_zona_id_1e662f03" ON "core_predio" ("zona_id");
CREATE TABLE "core_potrero" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(150) NOT NULL, "variedad" varchar(150) NOT NULL, "fecha_siembra" date NULL, "fecha_cosecha" date NULL, "superficie_ha" decimal NOT NULL, "perimetro" text NOT NULL CHECK ((JSON_VALID("perimetro") OR "perimetro" IS NULL)), "latitud" real NULL, "longitud" real NULL, "creado" datetime NOT NULL, "actualizado" datetime NOT NULL, "cultivo_id" bigint NULL REFERENCES "core_cultivo" ("id") DEFERRABLE INITIALLY DEFERRED, "predio_id" bigint NOT NULL REFERENCES "core_predio" ("id") DEFERRABLE INITIALLY DEFERRED, "geojson" text NULL CHECK ((JSON_VALID("geojson") OR "geojson" IS NULL)), CONSTRAINT "potrero_superficie_positiva" CHECK ("superficie_ha" > '0'));
CREATE INDEX "core_potrero_cultivo_id_e6b9b07b" ON "core_potrero" ("cultivo_id");
CREATE INDEX "core_potrero_predio_id_1faafb13" ON "core_potrero" ("predio_id");
CREATE TABLE "core_temporadacultivo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "variedad" varchar(150) NOT NULL, "fecha_siembra" date NULL, "fecha_cosecha" date NULL, "estado" varchar(12) NOT NULL, "observaciones" text NOT NULL, "creado" datetime NOT NULL, "actualizado" datetime NOT NULL, "cultivo_id" bigint NOT NULL REFERENCES "core_cultivo" ("id") DEFERRABLE INITIALLY DEFERRED, "potrero_id" bigint NOT NULL REFERENCES "core_potrero" ("id") DEFERRABLE INITIALLY DEFERRED, "temporada_agricola" varchar(9) NOT NULL);
CREATE INDEX "core_temporadacultivo_cultivo_id_d4c14c9e" ON "core_temporadacultivo" ("cultivo_id");
CREATE INDEX "core_temporadacultivo_potrero_id_928ab526" ON "core_temporadacultivo" ("potrero_id");
CREATE INDEX "temporada_potrero_fecha" ON "core_temporadacultivo" ("potrero_id", "fecha_siembra" DESC);
CREATE TABLE "core_calculoagricola" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "operacion" varchar(24) NOT NULL, "entrada" text NOT NULL CHECK ((JSON_VALID("entrada") OR "entrada" IS NULL)), "resultado" text NOT NULL CHECK ((JSON_VALID("resultado") OR "resultado" IS NULL)), "creado" datetime NOT NULL, "potrero_id" bigint NOT NULL REFERENCES "core_potrero" ("id") DEFERRABLE INITIALLY DEFERRED, "usuario_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX "core_calculoagricola_potrero_id_eae753cd" ON "core_calculoagricola" ("potrero_id");
CREATE INDEX "core_calculoagricola_usuario_id_4bf11325" ON "core_calculoagricola" ("usuario_id");
CREATE INDEX "calculo_usuario_fecha" ON "core_calculoagricola" ("usuario_id", "creado" DESC);
CREATE TABLE "core_actividadagricola" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(180) NOT NULL, "tipo" varchar(32) NOT NULL, "fecha_programada" date NOT NULL, "estado" varchar(12) NOT NULL, "observaciones" text NOT NULL, "creado" datetime NOT NULL, "actualizado" datetime NOT NULL, "potrero_id" bigint NOT NULL REFERENCES "core_potrero" ("id") DEFERRABLE INITIALLY DEFERRED, "usuario_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "condiciones_clima" varchar(255) NOT NULL, "dosis" decimal NULL, "fecha_realizada" date NULL, "insumo_id" bigint NULL REFERENCES "core_insumo" ("id") DEFERRABLE INITIALLY DEFERRED, "insumo_otro" varchar(150) NOT NULL, "objetivo" varchar(150) NOT NULL, "prioridad" varchar(8) NOT NULL, "responsable" varchar(150) NOT NULL, "superficie_ha" decimal NULL, "temporada_id" bigint NULL REFERENCES "core_temporadacultivo" ("id") DEFERRABLE INITIALLY DEFERRED, "unidad_dosis" varchar(20) NOT NULL);
CREATE INDEX "core_actividadagricola_potrero_id_dd4e13f8" ON "core_actividadagricola" ("potrero_id");
CREATE INDEX "core_actividadagricola_usuario_id_2e1ac1af" ON "core_actividadagricola" ("usuario_id");
CREATE INDEX "core_actividadagricola_insumo_id_a3653a6a" ON "core_actividadagricola" ("insumo_id");
CREATE INDEX "core_actividadagricola_temporada_id_cecbcfa8" ON "core_actividadagricola" ("temporada_id");
CREATE INDEX "actividad_usuario_estado_fecha" ON "core_actividadagricola" ("usuario_id", "estado", "fecha_programada");
